    "testCases": [
        {
            "group": "registerAndMergeDiscriminator_redefinePropertyName",
            "cases": [
                {
                    "input": [
                        {
                            "parameter": "currentDiscriminatorContext",
                            "value": "mock DiscriminatorContext where getDiscriminatorForPath(any) returns a non‑null discriminator ObjectNode"
                        },
                        {
                            "parameter": "discriminator",
                            "value": "empty ObjectNode (no \"mapping\" field)"
